#define readdir(d) tb_win_readdir(d)
#define closedir(d) tb_win_closedir(d)
#define isatty(fd) tb_win_isatty(fd)
#define sysconf(x) tb_win_sysconf(x)
#define localtime_r(t, r) (localtime_s((r), (t)) == 0 ? (r) : 0)
