    { const char * tb_v424 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v424; }
    { const char * tb_v425 = "// отдать общий замок целиком (задача уходит навсегда — падает или кончилась)\n"; *(const char * *)tb_grow(v_lines) = tb_v425; }
    { const char * tb_v426 = "TB_INL void tb_bkl_drop(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v426; }
