    { const char * tb_v560 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v560; }
    { const char * tb_v561 = "// память: запас 64 МБ. Куски по размерам 16, 32, 64, ... байт; отданный кусок\n"; *(const char * *)tb_grow(v_lines) = tb_v561; }
    { const char * tb_v562 = "// кладётся в корзину своего размера и выдаётся снова. Последний кусок отдаётся сразу.\n"; *(const char * *)tb_grow(v_lines) = tb_v562; }
    { const char * tb_v563 = "#define TB_HEAP (64 << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v563; }
    { const char * tb_v564 = "TB_API unsigned char tb_heap[TB_HEAP] __attribute__((aligned(16), section(\".tbheap\")));\n"; *(const char * *)tb_grow(v_lines) = tb_v564; }
    { const char * tb_v565 = "TB_API size_t tb_heap_top = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v565; }
    { const char * tb_v566 = "TB_API void *tb_bins[32];\n"; *(const char * *)tb_grow(v_lines) = tb_v566; }
    { const char * tb_v567 = "TB_API int tb_cls(size_t n) { int k = 4; while (k < 31 && ((size_t)1 << k) < n) k++; return k; }\n"; *(const char * *)tb_grow(v_lines) = tb_v567; }
    { const char * tb_v568 = "TB_API void *tb_malloc0(size_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v568; }
    { const char * tb_v569 = "    int k = tb_cls(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v569; }
    { const char * tb_v570 = "    if (tb_bins[k]) { void *p = tb_bins[k]; tb_bins[k] = *(void **)p; return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v570; }
    { const char * tb_v571 = "    size_t need = ((size_t)1 << k) + 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v571; }
    { const char * tb_v572 = "    if (tb_heap_top + need > TB_HEAP) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v572; }
    { const char * tb_v573 = "    unsigned char *h = tb_heap + tb_heap_top;\n"; *(const char * *)tb_grow(v_lines) = tb_v573; }
    { const char * tb_v574 = "    *(size_t *)h = (size_t)k;\n"; *(const char * *)tb_grow(v_lines) = tb_v574; }
    { const char * tb_v575 = "    tb_heap_top += need;\n"; *(const char * *)tb_grow(v_lines) = tb_v575; }
    { const char * tb_v576 = "    return h + 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v576; }
    { const char * tb_v577 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v577; }
    { const char * tb_v578 = "TB_API void tb_free0(void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v578; }
    { const char * tb_v579 = "    if (p == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v579; }
    { const char * tb_v580 = "    unsigned char *h = (unsigned char *)p - 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v580; }
