    { const char * tb_v583 = "    *(void **)p = tb_bins[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v583; }
    { const char * tb_v584 = "    tb_bins[k] = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v584; }
