    { const char * tb_v586 = "// квота клетки: каждый кусок помнит хозяина (в заголовке, за размером); у клетки — счёт байт.\n"; *(const char * *)tb_grow(v_lines) = tb_v586; }
    { const char * tb_v587 = "// Клетка, взявшая больше своей квоты, падает одна (main и прерывания без квоты)\n"; *(const char * *)tb_grow(v_lines) = tb_v587; }
