    { const char * tb_v827 = "TB_API uint64_t tb_tls_size(void) { return (uint64_t)(tb_tls_end - tb_tls_start); }\n"; *(const char * *)tb_grow(v_lines) = tb_v827; }
    { const char * tb_v828 = "// блок переменных потока: начальные значения (образ от компоновщика), в конце — адрес конца\n"; *(const char * *)tb_grow(v_lines) = tb_v828; }
    { const char * tb_v829 = "// (так устроено у x86-64: FS указывает на конец блока, а там лежит он сам)\n"; *(const char * *)tb_grow(v_lines) = tb_v829; }
    { const char * tb_v830 = "TB_API unsigned char *tb_tls_fresh(unsigned char *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v830; }
    { const char * tb_v831 = "    uint64_t n = tb_tls_size();\n"; *(const char * *)tb_grow(v_lines) = tb_v831; }
