    { const char * tb_v843 = "// хозяин куска: номер слота и поколение; кусок клетки, которой уже нет, никому не засчитывается\n"; *(const char * *)tb_grow(v_lines) = tb_v843; }
    { const char * tb_v844 = "TB_API uint64_t tb_cell_charge(size_t bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v844; }
    { const char * tb_v845 = "    if (tb_in_irq) return 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v845; }
    { const char * tb_v846 = "    tb_kslot *s = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v846; }
    { const char * tb_v847 = "    if (tb_cur != 0 && s->mem + (long long)bytes > TB_CELL_QUOTA) return (uint64_t)-1;\n"; *(const char * *)tb_grow(v_lines) = tb_v847; }
    { const char * tb_v848 = "    s->mem += (long long)bytes;\n"; *(const char * *)tb_grow(v_lines) = tb_v848; }
    { const char * tb_v849 = "    return (uint64_t)tb_cur | (s->gen << 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v849; }
    { const char * tb_v850 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v850; }
    { const char * tb_v851 = "// хватит ли клетке квоты, если её кусок вырастет на месте (иначе растём через malloc — он и уронит)\n"; *(const char * *)tb_grow(v_lines) = tb_v851; }
    { const char * tb_v852 = "TB_API int tb_cell_fits(uint64_t tag, long long more) {\n"; *(const char * *)tb_grow(v_lines) = tb_v852; }
    { const char * tb_v853 = "    uint64_t i = tag & 0xFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v853; }
    { const char * tb_v854 = "    if (i == 0 || i >= TB_NTASK || tb_slots[i].gen != (tag >> 8)) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v854; }
    { const char * tb_v855 = "    return tb_slots[i].mem + more <= TB_CELL_QUOTA;\n"; *(const char * *)tb_grow(v_lines) = tb_v855; }
    { const char * tb_v856 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v856; }
    { const char * tb_v857 = "TB_API void tb_cell_refund(uint64_t tag, long long bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v857; }
    { const char * tb_v858 = "    uint64_t i = tag & 0xFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v858; }
    { const char * tb_v859 = "    if (i >= TB_NTASK || tb_slots[i].gen != (tag >> 8) || !tb_slots[i].used) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v859; }
