    { const char * tb_v863 = "TB_API void tb_pic_apply(void) { tb_outb(0x21, (unsigned char)tb_pic_mask); tb_outb(0xA1, (unsigned char)(tb_pic_mask >> 8)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v863; }
    { const char * tb_v864 = "TB_API void tb_irq_set(int v, void (*fn)(void)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v864; }
    { const char * tb_v865 = "    tb_irq_fn[v - 32] = fn;\n"; *(const char * *)tb_grow(v_lines) = tb_v865; }
