    { const char * tb_v869 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v869; }
    { const char * tb_v870 = "TB_API void tb_irq_on(void) { __asm__ volatile(\"sti\" ::: \"memory\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v870; }
