    { const char * tb_v873 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v873; }
    { const char * tb_v874 = "// переключение задач: запомнить кадр и «переменные потока» текущей, отдать кадр следующей\n"; *(const char * *)tb_grow(v_lines) = tb_v874; }
    { const char * tb_v875 = "TB_API uint64_t *tb_schedule(uint64_t *frame) {\n"; *(const char * *)tb_grow(v_lines) = tb_v875; }
    { const char * tb_v876 = "    tb_cpu *c = tb_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v876; }
    { const char * tb_v877 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v877; }
    { const char * tb_v878 = "    // слот задачи, которая кончилась на этом ядре раньше: теперь мы точно не на её стеке\n"; *(const char * *)tb_grow(v_lines) = tb_v878; }
    { const char * tb_v879 = "    if (c->to_free > 0) { tb_slots[c->to_free].used = 0; tb_nlive--; c->to_free = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v879; }
    { const char * tb_v880 = "    int cur = c->run;\n"; *(const char * *)tb_grow(v_lines) = tb_v880; }
