    { const char * tb_v882 = "    // следующая по кругу: живая и не идущая на другом ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v882; }
    { const char * tb_v883 = "    int n = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v883; }
