    { const char * tb_v885 = "        int j = ((cur < 0 ? 0 : cur) + k) % TB_NTASK;\n"; *(const char * *)tb_grow(v_lines) = tb_v885; }
    { const char * tb_v886 = "        tb_kslot *s = &tb_slots[j];\n"; *(const char * *)tb_grow(v_lines) = tb_v886; }
    { const char * tb_v887 = "        if (s->used && !s->done && (s->on < 0 || j == cur)) { n = j; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v887; }
    { const char * tb_v888 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v888; }
    { const char * tb_v889 = "    if (cur >= 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v889; }
    { const char * tb_v890 = "        tb_slots[cur].on = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v890; }
    { const char * tb_v891 = "        if (tb_slots[cur].done && cur != 0) c->to_free = cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v891; }
    { const char * tb_v892 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v892; }
    { const char * tb_v893 = "    uint64_t *next;\n"; *(const char * *)tb_grow(v_lines) = tb_v893; }
