    { const char * tb_v1420 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1420; }
    { const char * tb_v1421 = "TB_COLD TB_API void tb_crash(int line, const char *msg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1421; }
    { const char * tb_v1422 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v1422; }
