    { const char * tb_v1443 = "// исключений (tb_guard_init ниже), а место для него в конце стека даёт\n"; *(const char * *)tb_grow(v_lines) = tb_v1443; }
    { const char * tb_v1444 = "// SetThreadStackGuarantee. Этот sigaltstack только помнит память потока,\n"; *(const char * *)tb_grow(v_lines) = tb_v1444; }
    { const char * tb_v1445 = "// чтобы tb_tramp_run мог её отдать, и просит у Windows запас стека.\n"; *(const char * *)tb_grow(v_lines) = tb_v1445; }
    { const char * tb_v1446 = "typedef struct { void *ss_sp; size_t ss_size; int ss_flags; } stack_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v1446; }
    { const char * tb_v1447 = "#define SS_DISABLE 4\n"; *(const char * *)tb_grow(v_lines) = tb_v1447; }
