    { const char * tb_v2266 = "// N одинаковых битов в конец (repeat N times: flags.add(true))\n"; *(const char * *)tb_grow(v_lines) = tb_v2266; }
    { const char * tb_v2267 = "TB_API void tb_bfill(tb_list *l, long long n, _Bool v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2267; }
    { const char * tb_v2268 = "    if (n <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2268; }
    { const char * tb_v2269 = "    if (l->cap < 0) tb_crash(0, \"список нельзя растить, пока по нему идёт each ... by N (и сам кусок растить нельзя)\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2269; }
    { const char * tb_v2270 = "    long long need = l->len + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v2270; }
