    { const char * tb_v2727 = "TB_API int tb_js_hex(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2727; }
    { const char * tb_v2728 = "    int v = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2728; }
