    { const char * tb_v2737 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2737; }
    { const char * tb_v2738 = "// строка JSON (p смотрит на \") → обычный текст\n"; *(const char * *)tb_grow(v_lines) = tb_v2738; }
    { const char * tb_v2739 = "TB_API const char *tb_js_str(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2739; }
    { const char * tb_v2740 = "    const char *e = tb_js_skip(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2740; }
    { const char * tb_v2741 = "    if (!e) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2741; }
    { const char * tb_v2742 = "    char *out = tb_tmem(e - p + 1), *o = out;\n"; *(const char * *)tb_grow(v_lines) = tb_v2742; }
