    { const char * tb_v2749 = "        else if (ch == 'b') *o++ = '\\b'; else if (ch == 'f') *o++ = '\\f';\n"; *(const char * *)tb_grow(v_lines) = tb_v2749; }
    { const char * tb_v2750 = "        else if (ch == 'u') {\n"; *(const char * *)tb_grow(v_lines) = tb_v2750; }
    { const char * tb_v2751 = "            int cp = tb_js_hex(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2751; }
    { const char * tb_v2752 = "            if (cp < 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2752; }
