    { const char * tb_v2759 = "            else if (cp < 0x800) { *o++ = (char)(0xC0 | (cp >> 6)); *o++ = (char)(0x80 | (cp & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2759; }
    { const char * tb_v2760 = "            else if (cp < 0x10000) { *o++ = (char)(0xE0 | (cp >> 12)); *o++ = (char)(0x80 | ((cp >> 6) & 63)); *o++ = (char)(0x80 | (cp & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2760; }
    { const char * tb_v2761 = "            else { *o++ = (char)(0xF0 | (cp >> 18)); *o++ = (char)(0x80 | ((cp >> 12) & 63)); *o++ = (char)(0x80 | ((cp >> 6) & 63)); *o++ = (char)(0x80 | (cp & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2761; }
