    { const char * tb_v2961 = "TB_API void tb_dreindex(tb_dict *d, long long nslots) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2961; }
    { const char * tb_v2962 = "    d->mode = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2962; }
