    { const char * tb_v3016 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3016; }
    { const char * tb_v3017 = "// --llvm: число ключей (из .ll не надо знать устройство tb_dict)\n"; *(const char * *)tb_grow(v_lines) = tb_v3017; }
    { const char * tb_v3018 = "TB_INL long long tb_dlen(tb_dict *d) { return d->keys->len; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3018; }
