    { const char * tb_v3029 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3029; }
    { const char * tb_v3030 = "// новый ключ int k: можно ли остаться без поиска (mode 1 или 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v3030; }
    { const char * tb_v3031 = "TB_API void tb_dplace_int(tb_dict *d, long long k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3031; }
    { const char * tb_v3032 = "    long long n = d->keys->len;          // уже вместе с новым ключом\n"; *(const char * *)tb_grow(v_lines) = tb_v3032; }
    { const char * tb_v3033 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3033; }
    { const char * tb_v3034 = "        if (n == 1) { d->base = k; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3034; }
