    { const char * tb_v3130 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3130; }
    { const char * tb_v3131 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3131; }
    { const char * tb_v3132 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3132; }
    { const char * tb_v3133 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v3133; }
    { const char * tb_v3134 = "TB_API void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3134; }
    { const char * tb_v3135 = "    t->done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3135; }
