    { const char * tb_v3165 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v3165; }
    { const char * tb_v3166 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3166; }
    { const char * tb_v3167 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3167; }
    { const char * tb_v3168 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3168; }
    { const char * tb_v3169 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v3169; }
    { const char * tb_v3170 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v3170; }
    { const char * tb_v3171 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v3171; }
    { const char * tb_v3172 = "TB_API pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3172; }
    { const char * tb_v3173 = "TB_API int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3173; }
    { const char * tb_v3174 = "    const char *want = getenv(\"TB_CORES\");   // TB_CORES=1 — проверить на одном ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v3174; }
    { const char * tb_v3175 = "    long n = want != 0 ? atol(want) : sysconf(_SC_NPROCESSORS_ONLN);\n"; *(const char * *)tb_grow(v_lines) = tb_v3175; }
    { const char * tb_v3176 = "    return n < 1 ? 1 : (n > 256 ? 256 : (int)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3176; }
    { const char * tb_v3177 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3177; }
    { const char * tb_v3178 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3178; }
    { const char * tb_v3179 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3179; }
    { const char * tb_v3180 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v3180; }
    { const char * tb_v3181 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v3181; }
    { const char * tb_v3182 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3182; }
    { const char * tb_v3183 = "    pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v3183; }
    { const char * tb_v3184 = "    for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3184; }
    { const char * tb_v3185 = "        if (pthread_create(&t[i], 0, work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3185; }
    { const char * tb_v3186 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3186; }
    { const char * tb_v3187 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3187; }
    { const char * tb_v3188 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3188; }
    { const char * tb_v3189 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3189; }
    { const char * tb_v3190 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v3190; }
    { const char * tb_v3191 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v3191; }
    { const char * tb_v3192 = "TB_API pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3192; }
    { const char * tb_v3193 = "TB_API pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3193; }
    { const char * tb_v3194 = "TB_API int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3194; }
    { const char * tb_v3195 = "TB_API volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3195; }
    { const char * tb_v3196 = "TB_API volatile int tb_pool_left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3196; }
    { const char * tb_v3197 = "TB_API void *(*tb_pool_work)(void *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3197; }
    { const char * tb_v3198 = "TB_API void *tb_pool_job = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3198; }
    { const char * tb_v3199 = "TB_API void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3199; }
    { const char * tb_v3200 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v3200; }
    { const char * tb_v3201 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v3201; }
    { const char * tb_v3202 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3202; }
    { const char * tb_v3203 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3203; }
    { const char * tb_v3204 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3204; }
    { const char * tb_v3205 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v3205; }
    { const char * tb_v3206 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3206; }
    { const char * tb_v3207 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v3207; }
    { const char * tb_v3208 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3208; }
    { const char * tb_v3209 = "        while (tb_pool_gen == seen) pthread_cond_wait(&tb_pool_go, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3209; }
    { const char * tb_v3210 = "        seen = tb_pool_gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v3210; }
    { const char * tb_v3211 = "        int mine = me < tb_pool_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v3211; }
    { const char * tb_v3212 = "        void *(*work)(void *) = tb_pool_work;\n"; *(const char * *)tb_grow(v_lines) = tb_v3212; }
    { const char * tb_v3213 = "        void *job = tb_pool_job;\n"; *(const char * *)tb_grow(v_lines) = tb_v3213; }
    { const char * tb_v3214 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3214; }
    { const char * tb_v3215 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v3215; }
    { const char * tb_v3216 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3216; }
    { const char * tb_v3217 = "        __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3217; }
    { const char * tb_v3218 = "        if (__atomic_sub_fetch(&tb_pool_left, 1, __ATOMIC_ACQ_REL) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3218; }
    { const char * tb_v3219 = "            pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3219; }
    { const char * tb_v3220 = "            pthread_cond_signal(&tb_pool_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v3220; }
    { const char * tb_v3221 = "            pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3221; }
    { const char * tb_v3222 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3222; }
    { const char * tb_v3223 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3223; }
