    { const char * tb_v3344 = "        if (a + n <= lo || a >= hi) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v3344; }
    { const char * tb_v3345 = "        if (!b->live) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3345; }
