    { const char * tb_v3348 = "            tb_mem_die(line, buf, b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3348; }
    { const char * tb_v3349 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3349; }
    { const char * tb_v3350 = "        if (a < b->a || a + n > b->a + b->n) tb_mem_die(line, \"чтение или запись за краем блока\", b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3350; }
