    { const char * tb_v3379 = "    if (chk) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3379; }
    { const char * tb_v3380 = "        memset(p + n, 0xFB, TB_MEM_GUARD);\n"; *(const char * *)tb_grow(v_lines) = tb_v3380; }
