    { const char * tb_v3393 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3393; }
    { const char * tb_v3394 = "// проверить адрес для free_mem / grow_mem; вернуть заголовок блока\n"; *(const char * *)tb_grow(v_lines) = tb_v3394; }
    { const char * tb_v3395 = "static tb_memh *tb_mem_own(long long a, int line, const char *who) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3395; }
    { const char * tb_v3396 = "    char buf[120];\n"; *(const char * *)tb_grow(v_lines) = tb_v3396; }
    { const char * tb_v3397 = "    if (tb_memchk()) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3397; }
    { const char * tb_v3398 = "        tb_mem_lock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3398; }
    { const char * tb_v3399 = "        tb_memb *b = tb_mem_find((uintptr_t)a);\n"; *(const char * *)tb_grow(v_lines) = tb_v3399; }
    { const char * tb_v3400 = "        if (!b) { snprintf(buf, sizeof buf, \"%s: это не адрес из new_mem\", who); tb_mem_die(line, buf, 0); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3400; }
    { const char * tb_v3401 = "        if (!b->live) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3401; }
    { const char * tb_v3402 = "            snprintf(buf, sizeof buf, \"%s: блок уже освобождён в строке %d\", who, b->fline);\n"; *(const char * *)tb_grow(v_lines) = tb_v3402; }
    { const char * tb_v3403 = "            tb_mem_die(line, buf, b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3403; }
    { const char * tb_v3404 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3404; }
    { const char * tb_v3405 = "        const unsigned char *g = (const unsigned char *)(uintptr_t)a + b->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3405; }
    { const char * tb_v3406 = "        for (int i = 0; i < TB_MEM_GUARD; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3406; }
    { const char * tb_v3407 = "            if (g[i] != 0xFB) tb_mem_die(line, \"кто-то писал за краем блока\", b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3407; }
    { const char * tb_v3408 = "        tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3408; }
