    { const char * tb_v3420 = "    b->live = 0; b->fline = line;\n"; *(const char * *)tb_grow(v_lines) = tb_v3420; }
    { const char * tb_v3421 = "    memset((void *)(uintptr_t)a, 0xDD, (size_t)b->n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3421; }
    { const char * tb_v3422 = "    ((tb_memh *)(uintptr_t)a - 1)->magic = TB_MEM_DEAD;\n"; *(const char * *)tb_grow(v_lines) = tb_v3422; }
    { const char * tb_v3423 = "    tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3423; }
    { const char * tb_v3424 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3424; }
    { const char * tb_v3425 = "// free_mem(адрес): отдать блок; free_mem(0) ничего не делает\n"; *(const char * *)tb_grow(v_lines) = tb_v3425; }
    { const char * tb_v3426 = "TB_API void tb_free_mem(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3426; }
    { const char * tb_v3427 = "    if (a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3427; }
    { const char * tb_v3428 = "    tb_memh *h = tb_mem_own(a, line, \"free_mem\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3428; }
    { const char * tb_v3429 = "    if (tb_memchk()) { tb_mem_bury(a, line); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3429; }
