    { const char * tb_v3432 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3432; }
    { const char * tb_v3433 = "// grow_mem(адрес, байт): блок нового размера (данные сохраняются, новое место — нули); адрес может стать другим\n"; *(const char * *)tb_grow(v_lines) = tb_v3433; }
    { const char * tb_v3434 = "TB_API long long tb_grow_mem(long long a, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3434; }
    { const char * tb_v3435 = "    if (a == 0) return tb_new_mem(n, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3435; }
    { const char * tb_v3436 = "    if (n <= 0) { tb_err = \"grow_mem: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3436; }
    { const char * tb_v3437 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"grow_mem: слишком большой блок\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3437; }
    { const char * tb_v3438 = "    tb_memh *h = tb_mem_own(a, line, \"grow_mem\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3438; }
    { const char * tb_v3439 = "    uint64_t old = h->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v3439; }
    { const char * tb_v3440 = "    if (tb_memchk()) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3440; }
    { const char * tb_v3441 = "        long long b = tb_new_mem(n, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3441; }
    { const char * tb_v3442 = "        if (!b) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3442; }
    { const char * tb_v3443 = "        memcpy((void *)(uintptr_t)b, (void *)(uintptr_t)a, (size_t)(old < (uint64_t)n ? old : (uint64_t)n));\n"; *(const char * *)tb_grow(v_lines) = tb_v3443; }
    { const char * tb_v3444 = "        tb_mem_bury(a, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3444; }
    { const char * tb_v3445 = "        return b;\n"; *(const char * *)tb_grow(v_lines) = tb_v3445; }
    { const char * tb_v3446 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3446; }
    { const char * tb_v3447 = "    tb_memh *q = realloc(h, sizeof(tb_memh) + (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3447; }
    { const char * tb_v3448 = "    if (!q) { tb_err = \"grow_mem: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3448; }
    { const char * tb_v3449 = "    if ((uint64_t)n > old) memset((unsigned char *)(q + 1) + old, 0, (size_t)((uint64_t)n - old));\n"; *(const char * *)tb_grow(v_lines) = tb_v3449; }
