    { const char * tb_v3452 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3452; }
    { const char * tb_v3453 = "// copy_mem(куда, откуда, байт): блоки могут перекрываться\n"; *(const char * *)tb_grow(v_lines) = tb_v3453; }
    { const char * tb_v3454 = "TB_API void tb_copy_mem(long long dst, long long src, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3454; }
    { const char * tb_v3455 = "    if (n < 0) tb_crash(line, \"copy_mem: число байт меньше нуля\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3455; }
    { const char * tb_v3456 = "    if (n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3456; }
    { const char * tb_v3457 = "    if (tb_memchk()) { tb_mem_touch((uintptr_t)src, (uint64_t)n, line); tb_mem_touch((uintptr_t)dst, (uint64_t)n, line); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3457; }
    { const char * tb_v3458 = "    memmove((void *)(uintptr_t)dst, (const void *)(uintptr_t)src, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3458; }
    { const char * tb_v3459 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3459; }
    { const char * tb_v3460 = "// ---------- use c: функции из C ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3460; }
    { const char * tb_v3461 = "// настоящее имя функции C (на Mac у имён в библиотеке спереди _)\n"; *(const char * *)tb_grow(v_lines) = tb_v3461; }
    { const char * tb_v3462 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v3462; }
    { const char * tb_v3463 = "#define TB_CSYM(s) __asm__(\"_\" s)\n"; *(const char * *)tb_grow(v_lines) = tb_v3463; }
