    { const char * tb_v3466 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3466; }
    { const char * tb_v3467 = "// текст из C: копия в память Tachbit (C может потом поменять или отдать свой); NULL → \"\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3467; }
    { const char * tb_v3468 = "TB_API const char *tb_ctext(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3468; }
    { const char * tb_v3469 = "    if (!p) return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3469; }
    { const char * tb_v3470 = "    size_t n = strlen(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v3470; }
    { const char * tb_v3471 = "    char *s = tb_tmem(n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3471; }
