    { const char * tb_v3473 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3473; }
    { const char * tb_v3474 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3474; }
    { const char * tb_v3475 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3475; }
    { const char * tb_v3476 = "// ---------- zone: область памяти. Много кусков берутся быстро и освобождаются разом ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3476; }
    { const char * tb_v3477 = "// Зона — цепочка больших кусков. zone_take отрезает от текущего куска (16 байт выравнивание, нули),\n"; *(const char * *)tb_grow(v_lines) = tb_v3477; }
    { const char * tb_v3478 = "// кончился кусок — берёт новый. zone_clear отдаёт всё, кроме первого куска; zone_free — всё.\n"; *(const char * *)tb_grow(v_lines) = tb_v3478; }
    { const char * tb_v3479 = "#define TB_ZONE_LIVE 0x5A4F4E454C495645ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v3479; }
    { const char * tb_v3480 = "typedef struct tb_zchunk { struct tb_zchunk *next; uint64_t size, used, pad; } tb_zchunk;   // 32 байта: данные с выравниванием 16\n"; *(const char * *)tb_grow(v_lines) = tb_v3480; }
    { const char * tb_v3481 = "typedef struct { uint64_t magic, step; tb_zchunk *first, *cur; } tb_zone;\n"; *(const char * *)tb_grow(v_lines) = tb_v3481; }
    { const char * tb_v3482 = "// данные куска: сразу за заголовком, с выравниванием 16 (malloc в ядре выравнивает меньше)\n"; *(const char * *)tb_grow(v_lines) = tb_v3482; }
    { const char * tb_v3483 = "#define TB_ZDATA(k) ((unsigned char *)(((uintptr_t)((k) + 1) + 15) & ~(uintptr_t)15))\n"; *(const char * *)tb_grow(v_lines) = tb_v3483; }
    { const char * tb_v3484 = "static tb_zchunk *tb_zone_chunk(uint64_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3484; }
    { const char * tb_v3485 = "    tb_zchunk *k = malloc(sizeof(tb_zchunk) + (size_t)n + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v3485; }
    { const char * tb_v3486 = "    if (!k) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3486; }
    { const char * tb_v3487 = "    k->next = 0; k->size = n; k->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3487; }
    { const char * tb_v3488 = "    memset(TB_ZDATA(k), 0, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3488; }
    { const char * tb_v3489 = "    return k;\n"; *(const char * *)tb_grow(v_lines) = tb_v3489; }
    { const char * tb_v3490 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3490; }
    { const char * tb_v3491 = "// zone_new(байт): первый кусок такого размера; дальше куски того же размера (или больше, если нужно)\n"; *(const char * *)tb_grow(v_lines) = tb_v3491; }
    { const char * tb_v3492 = "TB_API long long tb_zone_new(long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3492; }
    { const char * tb_v3493 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v3493; }
    { const char * tb_v3494 = "    if (n <= 0) { tb_err = \"zone_new: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3494; }
    { const char * tb_v3495 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"zone_new: слишком большой размер\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3495; }
