    { const char * tb_v4232 = "// ---------- шрифты TTF: свой чтец (таблицы glyf, без чужих библиотек) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4232; }
    { const char * tb_v4233 = "// Буква рисуется на процессоре один раз в маленькую картинку с прозрачностью (сглаживание),\n"; *(const char * *)tb_grow(v_lines) = tb_v4233; }
    { const char * tb_v4234 = "// дальше её рисуют и видеокарта, и процессор одинаково: точка = (цвет * a + фон * (255 - a)) / 255.\n"; *(const char * *)tb_grow(v_lines) = tb_v4234; }
    { const char * tb_v4235 = "typedef struct { unsigned char *d; size_t n; uint32_t glyf, loca, hmtx, cmap; int upem, locfmt, nglyphs, nhm, asc, desc, cfmt; } tb_font_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v4235; }
    { const char * tb_v4236 = "TB_API tb_font_t *tb_fonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4236; }
    { const char * tb_v4237 = "TB_API int tb_nfonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4237; }
    { const char * tb_v4238 = "static unsigned tb_u16(const tb_font_t *f, size_t o) { return o + 2 <= f->n ? (unsigned)(f->d[o] << 8 | f->d[o + 1]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4238; }
    { const char * tb_v4239 = "static int tb_s16(const tb_font_t *f, size_t o) { return (int16_t)tb_u16(f, o); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4239; }
    { const char * tb_v4240 = "static uint32_t tb_u32(const tb_font_t *f, size_t o) { return o + 4 <= f->n ? ((uint32_t)f->d[o] << 24 | (uint32_t)f->d[o + 1] << 16 | (uint32_t)f->d[o + 2] << 8 | f->d[o + 3]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4240; }
    { const char * tb_v4241 = "static uint32_t tb_ttf_table(const tb_font_t *f, size_t base, const char *tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4241; }
    { const char * tb_v4242 = "    unsigned n = tb_u16(f, base + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4242; }
    { const char * tb_v4243 = "    for (unsigned i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4243; }
    { const char * tb_v4244 = "        size_t e = base + 12 + 16 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v4244; }
    { const char * tb_v4245 = "        if (e + 16 <= f->n && memcmp(f->d + e, tag, 4) == 0) return tb_u32(f, e + 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v4245; }
    { const char * tb_v4246 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4246; }
    { const char * tb_v4247 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4247; }
    { const char * tb_v4248 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4248; }
    { const char * tb_v4249 = "TB_API void tb_gpu_blend_probe(void);   // TB_GPU_CHECK: проба смешивания букв (ниже)\n"; *(const char * *)tb_grow(v_lines) = tb_v4249; }
    { const char * tb_v4250 = "TB_API long long tb_load_font(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4250; }
    { const char * tb_v4251 = "    FILE *fp = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4251; }
    { const char * tb_v4252 = "    if (!fp) { tb_err = tb_cat(\"нет такого файла шрифта: \", path); return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4252; }
    { const char * tb_v4253 = "    fseek(fp, 0, SEEK_END); long sz = ftell(fp); fseek(fp, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v4253; }
    { const char * tb_v4254 = "    unsigned char *d = sz > 12 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4254; }
    { const char * tb_v4255 = "    if (!d || fread(d, 1, (size_t)sz, fp) != (size_t)sz) { fclose(fp); free(d); tb_err = \"не могу прочитать файл шрифта\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4255; }
    { const char * tb_v4256 = "    fclose(fp);\n"; *(const char * *)tb_grow(v_lines) = tb_v4256; }
    { const char * tb_v4257 = "    tb_font_t f = { d, (size_t)sz };\n"; *(const char * *)tb_grow(v_lines) = tb_v4257; }
    { const char * tb_v4258 = "    size_t base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4258; }
    { const char * tb_v4259 = "    if (memcmp(d, \"ttcf\", 4) == 0) base = tb_u32(&f, 12);   // сборник шрифтов (.ttc): берём первый\n"; *(const char * *)tb_grow(v_lines) = tb_v4259; }
    { const char * tb_v4260 = "    uint32_t head = tb_ttf_table(&f, base, \"head\"), maxp = tb_ttf_table(&f, base, \"maxp\"), hhea = tb_ttf_table(&f, base, \"hhea\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4260; }
    { const char * tb_v4261 = "    f.glyf = tb_ttf_table(&f, base, \"glyf\"); f.loca = tb_ttf_table(&f, base, \"loca\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4261; }
    { const char * tb_v4262 = "    f.hmtx = tb_ttf_table(&f, base, \"hmtx\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4262; }
    { const char * tb_v4263 = "    uint32_t cmap = tb_ttf_table(&f, base, \"cmap\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4263; }
    { const char * tb_v4264 = "    if (!f.glyf || !f.loca) { free(d); tb_err = \"этот шрифт не TrueType (контуры CFF/OTF пока не читаю): возьми .ttf\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4264; }
    { const char * tb_v4265 = "    if (!head || !maxp || !hhea || !f.hmtx || !cmap) { free(d); tb_err = \"шрифт сломан: нет нужных таблиц\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4265; }
    { const char * tb_v4266 = "    f.upem = (int)tb_u16(&f, head + 18); f.locfmt = tb_s16(&f, head + 50);\n"; *(const char * *)tb_grow(v_lines) = tb_v4266; }
    { const char * tb_v4267 = "    f.nglyphs = (int)tb_u16(&f, maxp + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4267; }
    { const char * tb_v4268 = "    f.asc = tb_s16(&f, hhea + 4); f.desc = tb_s16(&f, hhea + 6); f.nhm = (int)tb_u16(&f, hhea + 34);\n"; *(const char * *)tb_grow(v_lines) = tb_v4268; }
    { const char * tb_v4269 = "    if (f.upem <= 0 || f.nhm <= 0 || f.asc - f.desc <= 0) { free(d); tb_err = \"шрифт сломан: размеры\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4269; }
    { const char * tb_v4270 = "    // буквы → номера глифов: Unicode-таблица формата 12 (все буквы) или 4 (до U+FFFF)\n"; *(const char * *)tb_grow(v_lines) = tb_v4270; }
    { const char * tb_v4271 = "    unsigned nt = tb_u16(&f, cmap + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v4271; }
    { const char * tb_v4272 = "    int best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4272; }
    { const char * tb_v4273 = "    for (unsigned i = 0; i < nt; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4273; }
    { const char * tb_v4274 = "        size_t e = cmap + 4 + 8 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v4274; }
    { const char * tb_v4275 = "        unsigned pid = tb_u16(&f, e), eid = tb_u16(&f, e + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v4275; }
    { const char * tb_v4276 = "        uint32_t off = cmap + tb_u32(&f, e + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4276; }
    { const char * tb_v4277 = "        unsigned fmt = tb_u16(&f, off);\n"; *(const char * *)tb_grow(v_lines) = tb_v4277; }
    { const char * tb_v4278 = "        int score = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4278; }
    { const char * tb_v4279 = "        if (fmt == 12 && (pid == 0 || (pid == 3 && eid == 10))) score = 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v4279; }
    { const char * tb_v4280 = "        else if (fmt == 4 && (pid == 0 || (pid == 3 && eid == 1))) score = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v4280; }
    { const char * tb_v4281 = "        if (score > best) { best = score; f.cmap = off; f.cfmt = (int)fmt; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4281; }
    { const char * tb_v4282 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4282; }
    { const char * tb_v4283 = "    if (!best) { free(d); tb_err = \"в шрифте нет таблицы букв Unicode\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4283; }
    { const char * tb_v4284 = "    tb_font_t *all = realloc(tb_fonts, (size_t)(tb_nfonts + 1) * sizeof(tb_font_t));\n"; *(const char * *)tb_grow(v_lines) = tb_v4284; }
    { const char * tb_v4285 = "    if (!all) { free(d); tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4285; }
    { const char * tb_v4286 = "    tb_fonts = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v4286; }
    { const char * tb_v4287 = "    tb_fonts[tb_nfonts++] = f;\n"; *(const char * *)tb_grow(v_lines) = tb_v4287; }
    { const char * tb_v4288 = "    tb_gpu_blend_probe();\n"; *(const char * *)tb_grow(v_lines) = tb_v4288; }
    { const char * tb_v4289 = "    return tb_nfonts - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4289; }
    { const char * tb_v4290 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4290; }
    { const char * tb_v4291 = "static unsigned tb_ttf_glyph(const tb_font_t *f, unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4291; }
    { const char * tb_v4292 = "    size_t c = f->cmap;\n"; *(const char * *)tb_grow(v_lines) = tb_v4292; }
    { const char * tb_v4293 = "    if (f->cfmt == 12) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4293; }
    { const char * tb_v4294 = "        uint32_t n = tb_u32(f, c + 12);\n"; *(const char * *)tb_grow(v_lines) = tb_v4294; }
    { const char * tb_v4295 = "        for (uint32_t lo = 0, hi = n; lo < hi;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4295; }
    { const char * tb_v4296 = "            uint32_t mid = (lo + hi) / 2; size_t g = c + 16 + 12 * (size_t)mid;\n"; *(const char * *)tb_grow(v_lines) = tb_v4296; }
    { const char * tb_v4297 = "            uint32_t a = tb_u32(f, g), b = tb_u32(f, g + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4297; }
    { const char * tb_v4298 = "            if (u < a) hi = mid; else if (u > b) lo = mid + 1; else return tb_u32(f, g + 8) + (u - a);\n"; *(const char * *)tb_grow(v_lines) = tb_v4298; }
    { const char * tb_v4299 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4299; }
    { const char * tb_v4300 = "        return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4300; }
    { const char * tb_v4301 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4301; }
    { const char * tb_v4302 = "    if (u > 0xFFFF) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4302; }
    { const char * tb_v4303 = "    unsigned segs = tb_u16(f, c + 6) / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v4303; }
    { const char * tb_v4304 = "    size_t ends = c + 14, starts = ends + 2 * segs + 2, deltas = starts + 2 * segs, ranges = deltas + 2 * segs;\n"; *(const char * *)tb_grow(v_lines) = tb_v4304; }
    { const char * tb_v4305 = "    for (unsigned i = 0; i < segs; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4305; }
    { const char * tb_v4306 = "        if (u > tb_u16(f, ends + 2 * i)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v4306; }
    { const char * tb_v4307 = "        unsigned s = tb_u16(f, starts + 2 * i);\n"; *(const char * *)tb_grow(v_lines) = tb_v4307; }
    { const char * tb_v4308 = "        if (u < s) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4308; }
    { const char * tb_v4309 = "        unsigned delta = tb_u16(f, deltas + 2 * i), ro = tb_u16(f, ranges + 2 * i);\n"; *(const char * *)tb_grow(v_lines) = tb_v4309; }
    { const char * tb_v4310 = "        if (ro == 0) return (u + delta) & 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v4310; }
    { const char * tb_v4311 = "        unsigned g = tb_u16(f, ranges + 2 * i + ro + 2 * (u - s));\n"; *(const char * *)tb_grow(v_lines) = tb_v4311; }
    { const char * tb_v4312 = "        return g ? (g + delta) & 0xFFFF : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4312; }
    { const char * tb_v4313 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4313; }
    { const char * tb_v4314 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4314; }
    { const char * tb_v4315 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4315; }
    { const char * tb_v4316 = "static double tb_ttf_adv(const tb_font_t *f, unsigned g) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4316; }
    { const char * tb_v4317 = "    unsigned i = (int)g < f->nhm ? g : (unsigned)f->nhm - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4317; }
    { const char * tb_v4318 = "    return tb_u16(f, f->hmtx + 4 * (size_t)i);\n"; *(const char * *)tb_grow(v_lines) = tb_v4318; }
    { const char * tb_v4319 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4319; }
    { const char * tb_v4320 = "static size_t tb_ttf_gpos(const tb_font_t *f, unsigned g, size_t *len) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4320; }
    { const char * tb_v4321 = "    if ((int)g >= f->nglyphs) { *len = 0; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4321; }
    { const char * tb_v4322 = "    size_t a, b;\n"; *(const char * *)tb_grow(v_lines) = tb_v4322; }
    { const char * tb_v4323 = "    if (f->locfmt == 0) { a = 2 * (size_t)tb_u16(f, f->loca + 2 * g); b = 2 * (size_t)tb_u16(f, f->loca + 2 * g + 2); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4323; }
    { const char * tb_v4324 = "    else { a = tb_u32(f, f->loca + 4 * g); b = tb_u32(f, f->loca + 4 * g + 4); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4324; }
    { const char * tb_v4325 = "    *len = b > a ? b - a : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4325; }
    { const char * tb_v4326 = "    return f->glyf + a;\n"; *(const char * *)tb_grow(v_lines) = tb_v4326; }
    { const char * tb_v4327 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4327; }
    { const char * tb_v4328 = "// контур буквы → отрезки (в точках экрана, y вниз); m — матрица шрифт → экран: x' = m0 x + m2 y + m4, y' = m1 x + m3 y + m5\n"; *(const char * *)tb_grow(v_lines) = tb_v4328; }
    { const char * tb_v4329 = "typedef struct { float *e; int n, cap; } tb_edges;\n"; *(const char * *)tb_grow(v_lines) = tb_v4329; }
    { const char * tb_v4330 = "static void tb_edge(tb_edges *E, double x0, double y0, double x1, double y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4330; }
    { const char * tb_v4331 = "    if (y0 == y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4331; }
    { const char * tb_v4332 = "    if (E->n == E->cap) { E->cap = E->cap ? E->cap * 2 : 256; E->e = realloc(E->e, (size_t)E->cap * 4 * sizeof(float)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4332; }
    { const char * tb_v4333 = "    float *p = E->e + 4 * E->n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4333; }
    { const char * tb_v4334 = "    p[0] = (float)x0; p[1] = (float)y0; p[2] = (float)x1; p[3] = (float)y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4334; }
    { const char * tb_v4335 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4335; }
    { const char * tb_v4336 = "static void tb_quad(tb_edges *E, double x0, double y0, double cx, double cy, double x1, double y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4336; }
    { const char * tb_v4337 = "    double dx = x0 - 2 * cx + x1, dy = y0 - 2 * cy + y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4337; }
    { const char * tb_v4338 = "    int n = 1 + (int)sqrt(sqrt(dx * dx + dy * dy) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4338; }
    { const char * tb_v4339 = "    if (n > 16) n = 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v4339; }
    { const char * tb_v4340 = "    double px = x0, py = y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4340; }
    { const char * tb_v4341 = "    for (int i = 1; i <= n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4341; }
    { const char * tb_v4342 = "        double t = (double)i / n, u = 1 - t;\n"; *(const char * *)tb_grow(v_lines) = tb_v4342; }
