    { const char * tb_v4696 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4696; }
    { const char * tb_v4697 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4697; }
