    { const char * tb_v4703 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v4703; }
    { const char * tb_v4704 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v4704; }
    { const char * tb_v4705 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4705; }
    { const char * tb_v4706 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v4706; }
    { const char * tb_v4707 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v4707; }
