    { const char * tb_v7190 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v7190; }
    { const char * tb_v7191 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v7191; }
    { const char * tb_v7192 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v7192; }
    { const char * tb_v7193 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v7193; }
    { const char * tb_v7194 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v7194; }
    { const char * tb_v7195 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7195; }
    { const char * tb_v7196 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7196; }
    { const char * tb_v7197 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v7197; }
    { const char * tb_v7198 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7198; }
    { const char * tb_v7199 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7199; }
    { const char * tb_v7200 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v7200; }
    { const char * tb_v7201 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7201; }
    { const char * tb_v7202 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v7202; }
    { const char * tb_v7203 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v7203; }
    { const char * tb_v7204 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v7204; }
    { const char * tb_v7205 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7205; }
    { const char * tb_v7206 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7206; }
    { const char * tb_v7207 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v7207; }
    { const char * tb_v7208 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v7208; }
    { const char * tb_v7209 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v7209; }
    { const char * tb_v7210 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7210; }
    { const char * tb_v7211 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7211; }
    { const char * tb_v7212 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7212; }
    { const char * tb_v7213 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7213; }
    { const char * tb_v7214 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7214; }
    { const char * tb_v7215 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v7215; }
    { const char * tb_v7216 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v7216; }
    { const char * tb_v7217 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v7217; }
    { const char * tb_v7218 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v7218; }
    { const char * tb_v7219 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7219; }
    { const char * tb_v7220 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7220; }
    { const char * tb_v7221 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7221; }
    { const char * tb_v7222 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7222; }
    { const char * tb_v7223 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7223; }
    { const char * tb_v7224 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7224; }
    { const char * tb_v7225 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v7225; }
    { const char * tb_v7226 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7226; }
    { const char * tb_v7227 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7227; }
    { const char * tb_v7228 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7228; }
    { const char * tb_v7229 = "    tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7229; }
    { const char * tb_v7230 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7230; }
    { const char * tb_v7231 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7231; }
    { const char * tb_v7232 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v7232; }
    { const char * tb_v7233 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7233; }
    { const char * tb_v7234 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7234; }
    { const char * tb_v7235 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v7235; }
    { const char * tb_v7236 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7236; }
    { const char * tb_v7237 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7237; }
    { const char * tb_v7238 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v7238; }
    { const char * tb_v7239 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v7239; }
    { const char * tb_v7240 = "            diff += lut[i] != w;\n"; *(const char * *)tb_grow(v_lines) = tb_v7240; }
    { const char * tb_v7241 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7241; }
    { const char * tb_v7242 = "        fprintf(stderr, \"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: %lld из %d\\n\", diff, 1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v7242; }
    { const char * tb_v7243 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7243; }
    { const char * tb_v7244 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7244; }
    { const char * tb_v7245 = "// window_sharp(): окно в настоящих точках экрана (Retina, 150% и 200% на Windows). Размер в window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v7245; }
    { const char * tb_v7246 = "// остаётся в «обычных» точках, а кадр, window_w/h и мышь — в настоящих; window_scale() — во сколько раз\n"; *(const char * *)tb_grow(v_lines) = tb_v7246; }
    { const char * tb_v7247 = "TB_API double tb_gfx_scale(void);   // своя у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v7247; }
    { const char * tb_v7248 = "TB_API void tb_window_sharp(void) { if (!tb_px) tb_sharp = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7248; }
    { const char * tb_v7249 = "TB_API double tb_window_scale(void) { return tb_sc; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7249; }
    { const char * tb_v7250 = "TB_API void tb_window_open(long long w, long long h, const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7250; }
    { const char * tb_v7251 = "    if (tb_px) { tb_err = \"окно уже открыто\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7251; }
    { const char * tb_v7252 = "    if (w < 1 || h < 1 || w > 8192 || h > 8192) { tb_err = \"размер окна от 1 до 8192\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7252; }
    { const char * tb_v7253 = "    if (tb_sharp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7253; }
    { const char * tb_v7254 = "        tb_sc = tb_gfx_scale();\n"; *(const char * *)tb_grow(v_lines) = tb_v7254; }
    { const char * tb_v7255 = "        if (tb_sc < 1) tb_sc = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7255; }
    { const char * tb_v7256 = "        if (tb_sc > 4) tb_sc = 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v7256; }
    { const char * tb_v7257 = "        w = (long long)(w * tb_sc + 0.5); h = (long long)(h * tb_sc + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v7257; }
    { const char * tb_v7258 = "        if (w > 8192) w = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v7258; }
    { const char * tb_v7259 = "        if (h > 8192) h = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v7259; }
    { const char * tb_v7260 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7260; }
    { const char * tb_v7261 = "    tb_gw = (int)w; tb_gh = (int)h;\n"; *(const char * *)tb_grow(v_lines) = tb_v7261; }
    { const char * tb_v7262 = "    tb_px = calloc((size_t)tb_gw * tb_gh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v7262; }
    { const char * tb_v7263 = "    if (!tb_gfx_open(title)) { free(tb_px); tb_px = 0; tb_err = \"не могу открыть окно: нет экрана\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7263; }
    { const char * tb_v7264 = "    if (tb_gpu_on && tb_gpu_check) { atexit(tb_gpu_report); tb_gpu_blend_probe(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7264; }
    { const char * tb_v7265 = "    tb_last_frame = tb_time_ms();\n"; *(const char * *)tb_grow(v_lines) = tb_v7265; }
    { const char * tb_v7266 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7266; }
    { const char * tb_v7267 = "// показать кадр, принять клавиши и мышь, держать 60 кадров в секунду; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v7267; }
    { const char * tb_v7268 = "// окно поменяло размер: новый кадр, старое остаётся в левом верхнем углу, новое место — чёрное\n"; *(const char * *)tb_grow(v_lines) = tb_v7268; }
    { const char * tb_v7269 = "TB_API void tb_apply_resize(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7269; }
    { const char * tb_v7270 = "    if (!tb_new_w) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7270; }
    { const char * tb_v7271 = "    int nw = tb_new_w > 8192 ? 8192 : tb_new_w, nh = tb_new_h > 8192 ? 8192 : tb_new_h, ow = tb_gw, oh = tb_gh;\n"; *(const char * *)tb_grow(v_lines) = tb_v7271; }
    { const char * tb_v7272 = "    tb_new_w = tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7272; }
    { const char * tb_v7273 = "    if (nw < 1 || nh < 1 || (nw == ow && nh == oh)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7273; }
    { const char * tb_v7274 = "    uint32_t *np = calloc((size_t)nw * nh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v7274; }
    { const char * tb_v7275 = "    if (!np) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7275; }
    { const char * tb_v7276 = "    for (int y = 0; y < oh && y < nh; y++) memcpy(np + (size_t)y * nw, tb_px + (size_t)y * ow, (size_t)(ow < nw ? ow : nw) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v7276; }
    { const char * tb_v7277 = "    free(tb_px);\n"; *(const char * *)tb_grow(v_lines) = tb_v7277; }
    { const char * tb_v7278 = "    tb_px = np; tb_gw = nw; tb_gh = nh;\n"; *(const char * *)tb_grow(v_lines) = tb_v7278; }
    { const char * tb_v7279 = "    tb_gfx_reimage();\n"; *(const char * *)tb_grow(v_lines) = tb_v7279; }
    { const char * tb_v7280 = "    if (tb_gpu_on && !tb_gpu_resize(ow, oh)) fprintf(stderr, \"видеокарта: не получилось поменять размер кадра\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7280; }
    { const char * tb_v7281 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7281; }
    { const char * tb_v7282 = "TB_API long long tb_window_w(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gw; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7282; }
    { const char * tb_v7283 = "TB_API long long tb_window_h(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gh; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7283; }
    { const char * tb_v7284 = "// частота кадров: -1 — как у экрана (по умолчанию), 0 — сколько успеет, n — n кадров в секунду (set_fps)\n"; *(const char * *)tb_grow(v_lines) = tb_v7284; }
    { const char * tb_v7285 = "TB_API double tb_frame_ms_v = 16.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7285; }
    { const char * tb_v7286 = "TB_API long long tb_fps_want = -1, tb_fps_v = 0, tb_fps_n = 0, tb_fps_t0 = 0, tb_last_us = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7286; }
    { const char * tb_v7287 = "TB_API void tb_set_fps(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7287; }
    { const char * tb_v7288 = "    if (n < 0) n = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7288; }
    { const char * tb_v7289 = "    tb_fps_want = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7289; }
    { const char * tb_v7290 = "    int nosync = n == 0 || getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7290; }
    { const char * tb_v7291 = "    if (nosync != tb_gpu_nosync) { tb_gpu_nosync = nosync; if (tb_gpu_on) tb_gpu_vsync(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7291; }
    { const char * tb_v7292 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7292; }
    { const char * tb_v7293 = "TB_API double tb_frame_ms(void) { return tb_frame_ms_v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7293; }
    { const char * tb_v7294 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7294; }
    { const char * tb_v7295 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v7295; }
    { const char * tb_v7296 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7296; }
    { const char * tb_v7297 = "    if (!tb_px || tb_gclosed) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7297; }
    { const char * tb_v7298 = "    tb_gfx_events();   // здесь показывается прошлый кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v7298; }
    { const char * tb_v7299 = "    tb_zclr = tb_gzclr = 1;   // новый кадр: глубина 3D начинается заново\n"; *(const char * *)tb_grow(v_lines) = tb_v7299; }
    { const char * tb_v7300 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v7300; }
    { const char * tb_v7301 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v7301; }
    { const char * tb_v7302 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7302; }
    { const char * tb_v7303 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7303; }
    { const char * tb_v7304 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7304; }
    { const char * tb_v7305 = "    if (!tb_last_us) tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v7305; }
    { const char * tb_v7306 = "    if (free_fps || tb_fps_want == 0) period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7306; }
    { const char * tb_v7307 = "    else if (tb_fps_want > 0) period = 1000000 / tb_fps_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v7307; }
    { const char * tb_v7308 = "    // как у экрана: видеокарта сама ждёт обновления экрана (60 Гц — 60 кадров, 120 Гц — 120);\n"; *(const char * *)tb_grow(v_lines) = tb_v7308; }
    { const char * tb_v7309 = "    // кадр пришёл быстрее 4 мс — экран частоту не держит, держим сами 60 кадров в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v7309; }
    { const char * tb_v7310 = "    else if (!tb_gpu_on || now - tb_last_us < 4000) period = 16667;\n"; *(const char * *)tb_grow(v_lines) = tb_v7310; }
    { const char * tb_v7311 = "    if (period && now - tb_last_us < period) { usleep((useconds_t)(period - (now - tb_last_us))); now = tb_time_us(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7311; }
    { const char * tb_v7312 = "    tb_frame_ms_v = (now - tb_last_us) / 1000.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7312; }
    { const char * tb_v7313 = "    tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v7313; }
    { const char * tb_v7314 = "    if (!tb_fps_t0) tb_fps_t0 = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v7314; }
    { const char * tb_v7315 = "    tb_fps_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7315; }
    { const char * tb_v7316 = "    if (now - tb_fps_t0 >= 1000000) { tb_fps_v = tb_fps_n * 1000000 / (now - tb_fps_t0); tb_fps_n = 0; tb_fps_t0 = now; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7316; }
    { const char * tb_v7317 = "    tb_last_frame = now / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v7317; }
    { const char * tb_v7318 = "    return !tb_gclosed;\n"; *(const char * *)tb_grow(v_lines) = tb_v7318; }
    { const char * tb_v7319 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7319; }
    { const char * tb_v7320 = "TB_INL void tb_put(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7320; }
    { const char * tb_v7321 = "    if (tb_px && x >= 0 && y >= 0 && x < tb_gw && y < tb_gh) tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v7321; }
    { const char * tb_v7322 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7322; }
    { const char * tb_v7323 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v7323; }
    { const char * tb_v7324 = "// TB_GPU_CHECK=1: и то и другое, кадры сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v7324; }
    { const char * tb_v7325 = "#define TB_CPU_DRAW (!tb_gpu_on || tb_gpu_check)\n"; *(const char * *)tb_grow(v_lines) = tb_v7325; }
    { const char * tb_v7326 = "TB_API void tb_clear_window(long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7326; }
    { const char * tb_v7327 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7327; }
    { const char * tb_v7328 = "    if (tb_gpu_on) { tb_gin = 0; tb_gpu_rect(0, 0, tb_gw, tb_gh, c); }   // всё прежнее закрашено\n"; *(const char * *)tb_grow(v_lines) = tb_v7328; }
    { const char * tb_v7329 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v7329; }
    { const char * tb_v7330 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7330; }
    { const char * tb_v7331 = "TB_API void tb_draw_pixel(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7331; }
    { const char * tb_v7332 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7332; }
    { const char * tb_v7333 = "    if (tb_gpu_on) tb_gpu_rect(x, y, 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7333; }
    { const char * tb_v7334 = "    if (TB_CPU_DRAW) tb_put(x, y, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7334; }
    { const char * tb_v7335 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7335; }
    { const char * tb_v7336 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7336; }
    { const char * tb_v7337 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v7337; }
    { const char * tb_v7338 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v7338; }
    { const char * tb_v7339 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7339; }
    { const char * tb_v7340 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7340; }
    { const char * tb_v7341 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7341; }
    { const char * tb_v7342 = "    if (tb_gpu_on) tb_gpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7342; }
    { const char * tb_v7343 = "    if (TB_CPU_DRAW) tb_cpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7343; }
    { const char * tb_v7344 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7344; }
    { const char * tb_v7345 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7345; }
    { const char * tb_v7346 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7346; }
    { const char * tb_v7347 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7347; }
    { const char * tb_v7348 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v7348; }
    { const char * tb_v7349 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v7349; }
    { const char * tb_v7350 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v7350; }
    { const char * tb_v7351 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7351; }
    { const char * tb_v7352 = "            if (i * i + j * j <= r * r + r) tb_put(cx + i, cy + j, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7352; }
    { const char * tb_v7353 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7353; }
    { const char * tb_v7354 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7354; }
    { const char * tb_v7355 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7355; }
    { const char * tb_v7356 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7356; }
    { const char * tb_v7357 = "    long long dx = x1 > x0 ? x1 - x0 : x0 - x1, dy = y1 > y0 ? y0 - y1 : y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7357; }
    { const char * tb_v7358 = "    long long sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, e = dx + dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v7358; }
    { const char * tb_v7359 = "    int gpu = tb_gpu_on, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v7359; }
    { const char * tb_v7360 = "    while (1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7360; }
    { const char * tb_v7361 = "        if (gpu) tb_gpu_rect(x0, y0, 1, 1, c);   // соседние точки склеятся в полоски\n"; *(const char * *)tb_grow(v_lines) = tb_v7361; }
    { const char * tb_v7362 = "        if (cpu) tb_put(x0, y0, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7362; }
    { const char * tb_v7363 = "        if (x0 == x1 && y0 == y1) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v7363; }
    { const char * tb_v7364 = "        long long e2 = 2 * e;\n"; *(const char * *)tb_grow(v_lines) = tb_v7364; }
    { const char * tb_v7365 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7365; }
    { const char * tb_v7366 = "        if (e2 <= dx) { e += dx; y0 += sy; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7366; }
    { const char * tb_v7367 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7367; }
    { const char * tb_v7368 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7368; }
    { const char * tb_v7369 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v7369; }
    { const char * tb_v7370 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7370; }
    { const char * tb_v7371 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v7371; }
    { const char * tb_v7372 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v7372; }
    { const char * tb_v7373 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v7373; }
    { const char * tb_v7374 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v7374; }
    { const char * tb_v7375 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v7375; }
    { const char * tb_v7376 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7376; }
    { const char * tb_v7377 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v7377; }
    { const char * tb_v7378 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7378; }
    { const char * tb_v7379 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7379; }
    { const char * tb_v7380 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7380; }
    { const char * tb_v7381 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7381; }
    { const char * tb_v7382 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7382; }
    { const char * tb_v7383 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7383; }
    { const char * tb_v7384 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7384; }
    { const char * tb_v7385 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7385; }
    { const char * tb_v7386 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7386; }
    { const char * tb_v7387 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7387; }
    { const char * tb_v7388 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7388; }
    { const char * tb_v7389 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7389; }
    { const char * tb_v7390 = "    return !(x1 < 0 || y1 < 0 || x0 > tb_gw || y0 > tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v7390; }
    { const char * tb_v7391 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7391; }
    { const char * tb_v7392 = "TB_INL int tb_tri_edge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7392; }
    { const char * tb_v7393 = "    long long ex = bx - ax, ey = by - ay, e = ex * (2 * y + 1 - 2 * ay) - ey * (2 * x + 1 - 2 * ax);\n"; *(const char * *)tb_grow(v_lines) = tb_v7393; }
    { const char * tb_v7394 = "    return e > 0 || (e == 0 && (ey > 0 || (ey == 0 && ex < 0)));\n"; *(const char * *)tb_grow(v_lines) = tb_v7394; }
    { const char * tb_v7395 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7395; }
    { const char * tb_v7396 = "// глубина точки (x, y) по плоскости треугольника — так же, как в шейдере: 32-битные числа\n"; *(const char * *)tb_grow(v_lines) = tb_v7396; }
    { const char * tb_v7397 = "// без знака (переполнение по кругу), потом сдвиг; 0 — у самой камеры, 16777215 — далеко\n"; *(const char * *)tb_grow(v_lines) = tb_v7397; }
    { const char * tb_v7398 = "TB_INL uint32_t tb_tri3_depth(const uint32_t *pl, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7398; }
    { const char * tb_v7399 = "    uint32_t k = pl[2] + pl[0] * (uint32_t)(2 * x + 1) + pl[1] * (uint32_t)(2 * y + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7399; }
    { const char * tb_v7400 = "    int32_t d = (int32_t)k >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v7400; }
    { const char * tb_v7401 = "    return d < 0 ? 0u : d > 16777215 ? 16777215u : (uint32_t)d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7401; }
    { const char * tb_v7402 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7402; }
    { const char * tb_v7403 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v7403; }
    { const char * tb_v7404 = "// gpu, cpu — где рисовать (сетку на видеокарте может считать сама видеокарта: тогда здесь только процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v7404; }
    { const char * tb_v7405 = "static void tb_tri_draw_x(long long *t, long long c, const uint32_t *pl, int gpu, int cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7405; }
    { const char * tb_v7406 = "    if (!tb_tri_prep(t)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7406; }
    { const char * tb_v7407 = "    if (gpu) { if (pl) tb_gpu_tri3(t, c, pl); else tb_gpu_triangle(t, c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7407; }
    { const char * tb_v7408 = "    if (cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7408; }
    { const char * tb_v7409 = "        long long xa = t[0], xb = t[0], ya = t[1], yb = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7409; }
    { const char * tb_v7410 = "        for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7410; }
    { const char * tb_v7411 = "            if (t[i] < xa) xa = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7411; }
    { const char * tb_v7412 = "            if (t[i] > xb) xb = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7412; }
    { const char * tb_v7413 = "            if (t[i + 1] < ya) ya = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7413; }
    { const char * tb_v7414 = "            if (t[i + 1] > yb) yb = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7414; }
    { const char * tb_v7415 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7415; }
    { const char * tb_v7416 = "        if (xa < 0) xa = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7416; }
    { const char * tb_v7417 = "        if (ya < 0) ya = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7417; }
    { const char * tb_v7418 = "        if (xb > tb_gw - 1) xb = tb_gw - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7418; }
    { const char * tb_v7419 = "        if (yb > tb_gh - 1) yb = tb_gh - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7419; }
    { const char * tb_v7420 = "        for (long long y = ya; y <= yb; y++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7420; }
    { const char * tb_v7421 = "            for (long long x = xa; x <= xb; x++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7421; }
    { const char * tb_v7422 = "                if (tb_tri_edge(t[0], t[1], t[2], t[3], x, y) && tb_tri_edge(t[2], t[3], t[4], t[5], x, y) &&\n"; *(const char * *)tb_grow(v_lines) = tb_v7422; }
    { const char * tb_v7423 = "                    tb_tri_edge(t[4], t[5], t[0], t[1], x, y)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7423; }
    { const char * tb_v7424 = "                    if (pl) {   // 3D: точка видна, если ближе того, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v7424; }
    { const char * tb_v7425 = "                        uint32_t d = tb_tri3_depth(pl, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v7425; }
    { const char * tb_v7426 = "                        if (d >= tb_zb[y * tb_gw + x]) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v7426; }
    { const char * tb_v7427 = "                        tb_zb[y * tb_gw + x] = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7427; }
    { const char * tb_v7428 = "                    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7428; }
    { const char * tb_v7429 = "                    tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v7429; }
    { const char * tb_v7430 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v7430; }
    { const char * tb_v7431 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7431; }
    { const char * tb_v7432 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7432; }
    { const char * tb_v7433 = "static void tb_tri_draw_i(long long *t, long long c, const uint32_t *pl) { tb_tri_draw_x(t, c, pl, tb_gpu_on, TB_CPU_DRAW); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7433; }
    { const char * tb_v7434 = "// многоугольник с углами-дробями (3D после проекции, огромные треугольники): обрезаем рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v7434; }
    { const char * tb_v7435 = "// вокруг окна (±2048 точек, но не дальше ±8192), углы округляем, режем веером из первого угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v7435; }
    { const char * tb_v7436 = "// Общие углы округляются одинаково, поэтому соседние треугольники стыкуются без щелей\n"; *(const char * *)tb_grow(v_lines) = tb_v7436; }
    { const char * tb_v7437 = "// округление до ближайшего целого (половина — вверх); быстрее llround, одно и то же везде\n"; *(const char * *)tb_grow(v_lines) = tb_v7437; }
    { const char * tb_v7438 = "TB_INL long long tb_rnd(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7438; }
    { const char * tb_v7439 = "    long long r = (long long)(x + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v7439; }
    { const char * tb_v7440 = "    if ((double)r > x + 0.5) r--;\n"; *(const char * *)tb_grow(v_lines) = tb_v7440; }
    { const char * tb_v7441 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v7441; }
    { const char * tb_v7442 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7442; }
    { const char * tb_v7443 = "static void tb_poly_draw(double *px, double *py, int n, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7443; }
    { const char * tb_v7444 = "    double gx0 = -2048, gy0 = -2048, gx1 = tb_gw + 2048.0, gy1 = tb_gh + 2048.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7444; }
    { const char * tb_v7445 = "    if (gx1 > 8192) gx1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v7445; }
    { const char * tb_v7446 = "    if (gy1 > 8192) gy1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v7446; }
    { const char * tb_v7447 = "    double ax[16], ay[16], bx[16], by[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v7447; }
    { const char * tb_v7448 = "    for (int i = 0; i < n; i++) { ax[i] = px[i]; ay[i] = py[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7448; }
    { const char * tb_v7449 = "    for (int side = 0; side < 4 && n > 0; side++) {   // Сазерленд — Ходжман: по одной стороне рамки\n"; *(const char * *)tb_grow(v_lines) = tb_v7449; }
