    { const char * tb_v7498 = "TB_API void tb_draw_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7498; }
    { const char * tb_v7499 = "    if (!tb_px || id < 0 || id >= tb_nimg) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7499; }
