    { const char * tb_v7520 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7520; }
    { const char * tb_v7521 = "// текст: буква 8×16, size — во сколько раз крупнее\n"; *(const char * *)tb_grow(v_lines) = tb_v7521; }
    { const char * tb_v7522 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7522; }
    { const char * tb_v7523 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7523; }
    { const char * tb_v7524 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7524; }
    { const char * tb_v7525 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v7525; }
    { const char * tb_v7526 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v7526; }
    { const char * tb_v7527 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7527; }
    { const char * tb_v7528 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7528; }
    { const char * tb_v7529 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v7529; }
    { const char * tb_v7530 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7530; }
    { const char * tb_v7531 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v7531; }
    { const char * tb_v7532 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v7532; }
    { const char * tb_v7533 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7533; }
    { const char * tb_v7534 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v7534; }
    { const char * tb_v7535 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v7535; }
    { const char * tb_v7536 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v7536; }
    { const char * tb_v7537 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7537; }
    { const char * tb_v7538 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7538; }
    { const char * tb_v7539 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v7539; }
    { const char * tb_v7540 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v7540; }
    { const char * tb_v7541 = "        else if (u == 0x401) g = 159;\n"; *(const char * *)tb_grow(v_lines) = tb_v7541; }
    { const char * tb_v7542 = "        else if (u == 0x451) g = 160;\n"; *(const char * *)tb_grow(v_lines) = tb_v7542; }
    { const char * tb_v7543 = "        if (g < 0) g = '?' - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v7543; }
    { const char * tb_v7544 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v7544; }
    { const char * tb_v7545 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v7545; }
    { const char * tb_v7546 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7546; }
    { const char * tb_v7547 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v7547; }
    { const char * tb_v7548 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7548; }
    { const char * tb_v7549 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7549; }
    { const char * tb_v7550 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7550; }
    { const char * tb_v7551 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v7551; }
