    { const char * tb_v7798 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7798; }
    { const char * tb_v7799 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7799; }
    { const char * tb_v7800 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7800; }
    { const char * tb_v7801 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7801; }
    { const char * tb_v7802 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v7802; }
    { const char * tb_v7803 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7803; }
    { const char * tb_v7804 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7804; }
    { const char * tb_v7805 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v7805; }
    { const char * tb_v7806 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v7806; }
    { const char * tb_v7807 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7807; }
