    { const char * tb_v8114 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v8114; }
    { const char * tb_v8115 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8115; }
    { const char * tb_v8116 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v8116; }
    { const char * tb_v8117 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v8117; }
