    { const char * tb_v8131 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v8131; }
    { const char * tb_v8132 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v8132; }
    { const char * tb_v8133 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v8133; }
