    { const char * tb_v8213 = "// без устройства: время идёт как настоящее, звук — в файл (TB_SOUND_FILE) или никуда\n"; *(const char * *)tb_grow(v_lines) = tb_v8213; }
    { const char * tb_v8214 = "static void tb_snd_paced(FILE *f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8214; }
