    { const char * tb_v8390 = "// WAV: PCM 8/16/24/32 бита или float 32; моно или стерео (больше каналов — берём первые два)\n"; *(const char * *)tb_grow(v_lines) = tb_v8390; }
    { const char * tb_v8391 = "TB_API long long tb_load_sound(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8391; }
    { const char * tb_v8392 = "    FILE *f = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8392; }
    { const char * tb_v8393 = "    if (!f) { tb_err = \"нет такого файла звука\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8393; }
    { const char * tb_v8394 = "    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v8394; }
    { const char * tb_v8395 = "    unsigned char *b = sz > 0 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8395; }
    { const char * tb_v8396 = "    if (!b || fread(b, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(b); tb_err = \"не могу прочитать файл звука\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8396; }
    { const char * tb_v8397 = "    fclose(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v8397; }
    { const char * tb_v8398 = "    if (sz < 12 || memcmp(b, \"RIFF\", 4) != 0 || memcmp(b + 8, \"WAVE\", 4) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8398; }
    { const char * tb_v8399 = "        tb_err = sz >= 4 && memcmp(b, \"OggS\", 4) == 0 ? \"OGG пока не умею: сохрани звук как WAV\" : \"это не WAV-файл\";\n"; *(const char * *)tb_grow(v_lines) = tb_v8399; }
    { const char * tb_v8400 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v8400; }
    { const char * tb_v8401 = "        return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8401; }
    { const char * tb_v8402 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8402; }
    { const char * tb_v8403 = "    uint32_t tag = 0, ch = 0, rate = 0, bits = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8403; }
    { const char * tb_v8404 = "    const unsigned char *data = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8404; }
    { const char * tb_v8405 = "    uint32_t dlen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8405; }
    { const char * tb_v8406 = "    long p = 12;\n"; *(const char * *)tb_grow(v_lines) = tb_v8406; }
    { const char * tb_v8407 = "    while (p + 8 <= sz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8407; }
    { const char * tb_v8408 = "        uint32_t n = tb_le32(b + p + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8408; }
    { const char * tb_v8409 = "        const unsigned char *c = b + p + 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v8409; }
    { const char * tb_v8410 = "        if ((long)n > sz - p - 8) n = (uint32_t)(sz - p - 8);   // последний кусок обрезан — берём что есть\n"; *(const char * *)tb_grow(v_lines) = tb_v8410; }
    { const char * tb_v8411 = "        if (memcmp(b + p, \"fmt \", 4) == 0 && n >= 16) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8411; }
    { const char * tb_v8412 = "            tag = tb_le16(c); ch = tb_le16(c + 2); rate = tb_le32(c + 4); bits = tb_le16(c + 14);\n"; *(const char * *)tb_grow(v_lines) = tb_v8412; }
    { const char * tb_v8413 = "            if (tag == 0xFFFE && n >= 26) tag = tb_le16(c + 24);   // «расширенный» WAV: вид внутри\n"; *(const char * *)tb_grow(v_lines) = tb_v8413; }
    { const char * tb_v8414 = "        } else if (memcmp(b + p, \"data\", 4) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8414; }
    { const char * tb_v8415 = "            data = c; dlen = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8415; }
    { const char * tb_v8416 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8416; }
    { const char * tb_v8417 = "        p += 8 + (long)n + (n & 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8417; }
    { const char * tb_v8418 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8418; }
    { const char * tb_v8419 = "    int okf = (tag == 1 && (bits == 8 || bits == 16 || bits == 24 || bits == 32)) || (tag == 3 && (bits == 32 || bits == 64));\n"; *(const char * *)tb_grow(v_lines) = tb_v8419; }
    { const char * tb_v8420 = "    if (!data || !okf || ch == 0 || rate == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8420; }
    { const char * tb_v8421 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v8421; }
    { const char * tb_v8422 = "        tb_err = !data ? \"в WAV нет звука (нет куска data)\" : \"такой WAV не умею: нужен PCM 8/16/24/32 бита или float\";\n"; *(const char * *)tb_grow(v_lines) = tb_v8422; }
    { const char * tb_v8423 = "        return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8423; }
    { const char * tb_v8424 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8424; }
    { const char * tb_v8425 = "    uint32_t bpf = ch * (bits / 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v8425; }
