    { const char * tb_v8432 = "            const unsigned char *q = data + i * bpf + (uint32_t)k * (bits / 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v8432; }
    { const char * tb_v8433 = "            float v;\n"; *(const char * *)tb_grow(v_lines) = tb_v8433; }
