    { const char * tb_v8448 = "// свободный голос; заняты все — забираем самый тихий (лучше не тот, что играет по кругу)\n"; *(const char * *)tb_grow(v_lines) = tb_v8448; }
    { const char * tb_v8449 = "static long long tb_voice_new(long long s, int loop, int is3d, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8449; }
