    { const char * tb_v8492 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8492; }
    { const char * tb_v8493 = "    long long ramp = TB_SR / 200;\n"; *(const char * *)tb_grow(v_lines) = tb_v8493; }
    { const char * tb_v8494 = "    if (ramp * 2 > n) ramp = n / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8494; }
    { const char * tb_v8495 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8495; }
    { const char * tb_v8496 = "        double e = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8496; }
