    { const char * tb_v8498 = "        else if (i >= n - ramp) e = (double)(n - 1 - i) / ramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v8498; }
    { const char * tb_v8499 = "        d[i] = (float)(0.5 * e * sin(6.283185307179586 * hz * (double)i / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v8499; }
    { const char * tb_v8500 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8500; }
    { const char * tb_v8501 = "    long long s = tb_snd_add(d, n, 1, TB_SR, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8501; }
